<template><view class="page"><view class="head"><text>选一个场景</text><text>看看动画，学会新单词</text></view><view class="grid"><view v-for="item in rows" :key="item.scene_id" class="card" @click="open(item)"><text class="icon">{{ icon(item.title) }}</text><view><text class="title">{{ item.title }}</text><text class="desc">{{ item.description }}</text></view><text>开始 ›</text></view></view><view v-if="!rows.length" class="empty">场景正在准备中</view></view></template>
<script>
import { scenes } from '@/common/english-api'
export default { data() { return { rows: [] } }, async onShow() { try { this.rows = await scenes() } catch { uni.showToast({ title: '场景加载失败', icon: 'none' }) } }, methods: { icon(title) { return ({ 鱼类: '🐠', 禽类: '🦜', 昆虫: '🐝', 花: '🌸', 树: '🌳', 植物: '🌿', 爬行动物: '🐢', 甲壳动物: '🦀', 蠕虫: '🐛', 哺乳动物: '🦁', 动物: '🦓' })[title] || '✨' }, open(item) { uni.navigateTo({ url: `/pages/learn/words?sceneId=${item.scene_id}&title=${encodeURIComponent(item.title)}&animation=${encodeURIComponent(item.animation?.url || '')}` }) } } }
</script>
<style lang="scss" scoped>.page{min-height:100vh;padding:42rpx 8%;box-sizing:border-box;background:#f5fbff}.head text{display:block}.head text:first-child{font-size:48rpx;font-weight:800;color:#27425c}.head text:last-child{margin-top:12rpx;font-size:27rpx;color:#71849a}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:24rpx;margin-top:38rpx}.card{min-height:180rpx;padding:28rpx;box-sizing:border-box;border-radius:28rpx;background:#fff;box-shadow:0 10rpx 24rpx rgba(45,91,125,.1);display:grid;grid-template-columns:80rpx 1fr;gap:16rpx;align-items:center}.card:active{transform:scale(.98)}.icon{font-size:58rpx}.title,.desc{display:block}.title{font-size:31rpx;font-weight:800;color:#2c4058}.desc{margin-top:8rpx;font-size:22rpx;color:#7b8b9c}.card>text:last-child{grid-column:2;color:#4c8bd9;font-size:24rpx;font-weight:700}.empty{margin-top:60rpx;text-align:center;color:#8b98a7;font-size:28rpx}@media screen and (max-width:600px){.grid{grid-template-columns:1fr}}</style>
